var isUpdate = false;
var item = {};
this.addAdvancePayment = function  () {
	this.context.options.currencyVis.set("value", "READONLY");
	item = this.context.options.tmpUsedAdvancePayment.get("value");	
	if (isUpdate && item.get("AllocatedAmountinRequestCurrency")!=undefined && item.get("AllocatedAmountinRequestCurrency")!=null && this.context.options.tmpUsedAdvancePayment.get("value").get("AmountAllocated") > 0 && this.context.options.tmpUsedAdvancePayment.get("value").get("AmountAllocated") < this.context.options.tmpUsedAdvancePayment.get("value").get("outstandingAmount") && this.context.options.tmpUsedAdvancePayment.get("value").get("AllocatedAmountinRequestCurrency") > 0 ){
		var input = this.context.options.requestID.get("value") +"-"+ this.context.options.tmpUsedAdvancePayment.get("value").get("AllocatedAmountinRequestCurrency") +"-"+ this.context.options.tmpUsedAdvancePayment.get("value").get("AmountAllocated") +"-"+ this.context.options.tmpUsedAdvancePayment.get("value").get("DBID");
			
		this.ui.get("UpdateAdvancePaymentCall").execute(input);
		
	}
	else{
		if ( (item.get("AmountAllocated")!=undefined && item.get("AmountAllocated")!=null && item.get("AmountAllocated") > 0 && item.get("AmountAllocated") <= item.get("outstandingAmount") ) && (item.get("beneficiaryName")!=null && item.get("beneficiaryName")!= "" && item.get("beneficiaryName")!= undefined) && this.context.options.tmpUsedAdvancePayment.get("value").get("AllocatedAmountinRequestCurrency") > 0) {
//			this.ui.get("advancePaymentTable").appendElement(item);
			var input = this.context.options.requestID.get("value") +"-"+ this.context.options.tmpUsedAdvancePayment.get("value").get("AllocatedAmountinRequestCurrency") +"-"+ this.context.options.tmpUsedAdvancePayment.get("value").get("AmountAllocated") +"-"+ this.context.options.tmpUsedAdvancePayment.get("value").get("DBID");
			
			this.ui.get("AddAdvancePaymentCall").execute(input);
			

		}else{
			alert("can not add");
		}
	}

//	this.sumAllocated();
}
