var chargesIndex = 0;
var finalMinAmount = 0;
var firstDefaultAm = 0;
this.setInterestsAndCharges = function (){
	var j = 0;
	var defaultAmount = 0;
	// this.context.binding.get("value").set("haveInterest" , false);
	
	this.context.options.idcContract.get("value").set("commissionsAndCharges", []);
	for (var i=0; i<this.context.options.InterestAndChargesList.get("value").length() ; i++) {
	if (this.context.options.InterestAndChargesList.get("value").get(i).get("ruleType") != null &&
		this.context.options.InterestAndChargesList.get("value").get(i).get("ruleType") != ""&&
		this.context.options.InterestAndChargesList.get("value").get(i).get("ruleType") != undefined) {
		if (this.context.options.InterestAndChargesList.get("value").get(i).get("ruleType") == "Interest" 
			&& this.context.binding.get("value").get("IDCRequestType").get("englishdescription") != "ICAP" 
			&& this.context.binding.get("value").get("IDCRequestType").get("englishdescription")!="IDC Payment") 
		{
			// this.context.binding.get("value").set("haveInterest" , true);
			// this.ui.get("contract_Interest_Details").setVisible(true,true);
			alert("Interest Found : "+ this.context.options.idcContract.get("value").get("interestRate"));
			this.context.options.interestVis.set("value", "EDITABLE");
			this.context.options.idcContract.get("value").set("interestRate", this.context.options.InterestAndChargesList.get("value").get(i).get("rate"));

		}else if (this.context.options.InterestAndChargesList.get("value").get(i).get("ruleType") == "Charge"){
			this.context.options.idcContract.get("value").get("commissionsAndCharges").add({});
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("defaultCurrency",{});
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("defaultCurrency").set("code", this.context.options.InterestAndChargesList.get("value").get(i).get("basisAmountCurrency"));
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("component", this.context.options.InterestAndChargesList.get("value").get(i).get("component"));
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("debitedAccount", {});
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("debitedAccount").set("accountClass", "Customer Account");
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("debitedAccount").set("isGLVerifiedC", false);
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("debitedAccount").set("accountCurrency", {});
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("debitedAccount").set("isGLFoundC", true);
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("waiver", false);
			this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("debitedAmount", {});
			alert("Charges Found: " + this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("defaultCurrency").get("code"));
			
			//Caluc Default Amount
			if (this.context.options.InterestAndChargesList.get("value").get(i).get("rateType") == "Flat Amount") {
				defaultAmount = this.context.options.InterestAndChargesList.get("value").get(i).get("flatAmount");
			}else if (this.context.options.InterestAndChargesList.get("value").get(i).get("rateType") == "Fixed Rate"){
				var rate = this.context.options.InterestAndChargesList.get("value").get(i).get("rate");
				defaultAmount = rate / 100 * (this.context.binding.get("value").get("financialDetails").get("amtPayableByNBE"));
			}
			
			//Compare with Min Amount
			var minAmount = this.context.options.InterestAndChargesList.get("value").get(i).get("minAmount");
			if (minAmount > 0) {
				if (this.context.options.InterestAndChargesList.get("value").get(i).get("basisAmountCurrency") == 
					this.context.binding.get("value").get("financialDetails").get("documentCurrency").get("code")) {
					this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("defaultAmount", minAmount);
					this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("chargeAmount", this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("defaultAmount"));
				}else{
					finalMinAmount = minAmount;
					firstDefaultAm = defaultAmount;
					chargesIndex =  j;
					var basisC = this.context.options.InterestAndChargesList.get("value").get(i).get("basisAmountCurrency");
					var requestC = this.context.binding.get("value").get("financialDetails").get("documentCurrency").get("code");
					var concated = {ccFrom : basisC , ccTo : requestC , type:"TRANSFER" , sType:"S"};
					var concatExCurrency = JSON.stringify(concated);
					this.ui.get("GetExchangeRate").execute(concatExCurrency);
				}
			}else{
				this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("defaultAmount", defaultAmount);
				this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).set("chargeAmount", this.context.options.idcContract.get("value").get("commissionsAndCharges").get(j).get("defaultAmount"));
			}

			j+=1;
		}
	}
	}
}

this.exchangedDefaultAmount = function (){
	var record = chargesIndex;
	var rate = this.context.options.exRate.get("value");
	var minAm = finalMinAmount;
	var exMinAmount = rate * minAm;
	if (exMinAmount > firstDefaultAm) {
		this.context.options.idcContract.get("value").get("commissionsAndCharges").get(record).set("defaultAmount", exMinAmount);
	}else{
		this.context.options.idcContract.get("value").get("commissionsAndCharges").get(record).set("defaultAmount", firstDefaultAm);
	}
	this.context.options.idcContract.get("value").get("commissionsAndCharges").get(record).set("chargeAmount", this.context.options.idcContract.get("value").get("commissionsAndCharges").get(record).get("defaultAmount"));
}

