};

_this.getTabInfoFirst = function (tabSection) {
	const tabElementList = tabSection?.children;
	var tabsInfo = {};
	for (var i = 0; i < tabElementList.length; i++) {
		var tabElement = tabElementList[i];

		var tabInnerText = tabElement.innerText.split("\n")[0].replaceAll(" ", "");
		if (!tabInnerText || tabElement.getAttribute("role") !== "tab") continue;

		tabsInfo[tabInnerText] = {
			tabDomID: tabElement.id,
			tabPathId: i,
		};
	}

	return tabsInfo;
};

_this.resetRedCircle = function () {
	const redCircles = document.querySelectorAll(".red-circle");
	if (!redCircles) return null;
	redCircles.forEach((circle) => circle.remove());
};

_this.getTabSectionId = function (tabSection) {
	if (!tabSection) return;
	var currentElement = tabSection;

	while (currentElement && currentElement !== document.body) {
		if (currentElement.classList.contains("Tab_Section")) {
			tabSectionId = currentElement.getAttribute("control-name");
			break;
		}

		currentElement = currentElement.parentElement;
	}

	return tabSectionId;
};

_this.constructValidPanel = function (viewMapList) {
	if (!viewMapList || viewMapList.length == 0) return;
	var tabNameListHTML = "";

	for (let i = 0; i < viewMapList.length; i++) {
		var tabData = viewMapList[i].tab;
		var messageList = viewMapList[i].messages;

		if (!tabData) continue;

		var tabDomId = tabData.domId;
		var tabName = tabData.name || generalTab;
		var errorListId = `error-list-${tabDomId}`;
		var tabIndex = tabData.pathId;
		var errorListHTML = generateErrorListHTML(messageList, tabName, tabIndex);

		tabNameListHTML += generateTabItemHTML(
			tabName,
			tabDomId,
			errorListId,
			tabIndex,
			errorListHTML
		);
	}

	tabNameListHTML = `<ul class="tab-list">${tabNameListHTML}</ul>`;
	_this.ui.get(displayText).setText(tabNameListHTML);

	function generateErrorListHTML(listOfErrors, tabName, tabIndex) {
		return listOfErrors
			.map(function (error, i) {
				var fieldDomId = error.field.domId;
				var fieldPathId = error.field.pathId;
				var targetMessage = error.message;
				var panelString = "";
				error.field.panels.forEach((element) => {
					panelString += element + "@@";
				});

				return `<li><a href="#${fieldDomId}" class="message-link" message-id="${fieldDomId}" onclick="_this.activateField('${tabName}','${panelString}','${tabIndex}','${fieldPathId}');">${targetMessage}</a></li>`;
			})
			.join("");
	}

	function generateTabItemHTML(tabName, tabDomId, errorListId, tabIndex, errorListHTML) {
		return `<li class="tab-item">
			<div class="tab-container">
				<div class="tab-header">
				<a href="#${tabDomId}" class="tab-name"
					onclick="_this.activateTab('${tabDomId}','${tabName}','${tabIndex}');window.scrollTo(0,document.getElementById('${tabDomId}').offsetTop+150);">${tabName}:</a>
				<button id="toggleBtn_${errorListId}" class="toggle-btn" onclick="_this.toggleErrorList('${errorListId}');">&#11165;</button>
				</div>
				<ul id="${errorListId}" class="error-list" style="display:none;">${errorListHTML}</ul>
			</div>
		</li>`;
	}
};

_this.activateTab = function (tabDomId, tabName, tabIndex) {
	if (!tabName || !tabIndex) return;

	if (tabName !== generalTab) {
		page.ui.get(tabSectionId).setCurrentPane(tabIndex);
		if (tabDomId) {
			var tabElement = document.getElementById(tabDomId);
			_this.highLighElement(tabElement);
		}
	}
};

_this.toggleErrorList = function (errorListId) {
	if (!errorListId) return;

	var errorList = document.getElementById(errorListId);
	var toggleBtn = document.getElementById(`toggleBtn_${errorListId}`);

	if (errorList.style.display === "none" || errorList.style.display === "") {
		errorList.style.display = "block";
		toggleBtn.innerHTML = "&#11167;"; // Change to expanded icon
	} else {
		errorList.style.display = "none";
		toggleBtn.innerHTML = "&#11165;"; // Change to collapsed icon
	}

	toggleBtn.classList.toggle("collapsed");
};

_this.activateField = function (tabName, panelString, tabIndex, fieldPathId) {
	if (!fieldPathId) return;
	var panelList = panelString.split("@@").filter((e) => e !== "");
	// console.dir(panelList);
	if (tabIndex && tabSectionId && tabName !== generalTab) {
		page.ui.get(tabSectionId).setCurrentPane(tabIndex);
	}
	if (panelList && panelList.length > 0) {
		for (let i = 0; i < panelList.length; i++) {
			page.ui.get(panelList[i]).expand();
		}
		setTimeout(function () {
			_this.focusOnElement(fieldPathId);
		}, 300);
	}
	_this.focusOnElement(fieldPathId);
};

_this.focusOnElement = function (fieldPathId) {
	var fieldElement = page.ui.get(fieldPathId).context.element;
	_this.highLighElement(fieldElement);

	page.ui.get(fieldPathId).focus();
};

_this.highLighElement = function (fieldElement) {
	if (!fieldElement) return;

	fieldElement.classList.add("highlighted-field");
	setTimeout(function () {
		fieldElement.classList.remove("highlighted-field");
	}, 1500);
};

_this.addRedCircleToTab = function (viewMap) {
	if (!viewMap.tab.domId) return;

	const messagesCount = viewMap.messages.length;
	const tabDomId = viewMap.tab.domId;
	const tabElement = document.getElementById(tabDomId);
	if (!tabElement) return;

	const existingCircle = tabElement.querySelector(".red-circle");

	if (!existingCircle) {
		const redCircle = document.createElement("div");
		redCircle.classList.add("red-circle");
		redCircle.innerText = messagesCount;
		tabElement.appendChild(redCircle);
	} else {
		existingCircle.innerText = messagesCount;
	}
};

_this.constructErrorMap = function (fieldElement) {
	if (!fieldElement || !fieldElement.context.element || !fieldElement._bpmextViewNode)
		return null;

	var fieldDomId = fieldElement.context.element.id;
	var fieldParents = _this.getFieldParents(fieldDomId);
	var isField = Object.keys(fieldElement._bpmextViewNode._data.context.subview).length === 0;
	if (isField) {
		errorMap = {
			field: {
				message: fieldElement._bpmextVE?.errors?.[0]?.message || "",
				domId: fieldDomId,
				pathId: fieldElement.context.element.getAttribute("control-name"),
				viewId: fieldElement.context.element.getAttribute("data-viewid"),
			},

			panels: fieldParents.cPanelList /*[list of "SPARKCPanel"]*/,

			view: fieldParents.viewObj,
		};
		return errorMap;
	}
};

_this.getFieldParents = function (elementId) {
	var fieldParents = {
		viewObj: {
			name: "",
			domId: "",
			pathId: "",
		},
		cPanelList: [],
	};
	const cPanelClass = "Collapsible_Panel";
	const tabClass = "tab-pane";

	let currentElement = document.getElementById(elementId);

	while (currentElement && currentElement !== document.body) {
		if (currentElement.classList.contains(tabClass)) {
			fieldParents.viewObj.name = currentElement.getAttribute("aria-label");
			fieldParents.viewObj.domId = currentElement.id;
			fieldParents.viewObj.pathId = currentElement.getAttribute("control-name");
		} else if (currentElement.classList.contains(cPanelClass)) {
			fieldParents.cPanelList.unshift(currentElement.getAttribute("control-name"));
		}

		currentElement = currentElement.parentNode;
	}
	return fieldParents;
};

_this.organizeErrorsByTab = function (errorList) {
	const viewMap = new Map();
	var tabsInfo = {};
	if (tabSection) {
		tabsInfo = _this.getTabInfoFirst(tabSection);
	}

	errorList.forEach((error) => {
		if (error) {
			var viewName = error.view.name;
			if (viewName) {
				var tabName = viewName?.replaceAll(" ", "") + "";
			}

			if (!viewMap.has(viewName)) {
				viewMap.set(viewName, {
					view: {
						name: viewName,
						domId: error.view.domId,
						pathId: error.view.pathId,
					},
					messages: [],
					tab: {
						name: viewName,
						domId: tabsInfo[tabName]?.tabDomID,
						pathId: tabsInfo[tabName]?.tabPathId,
					},
				});
			}

			// Add the error message to the corresponding tab entry
			viewMap.get(viewName).messages.push({
				message: error.field.message,
				field: {
					domId: error.field.domId,
					pathId: error.field.pathId,
					viewId: error.field.viewId,
					panels: [...error.panels],
				},
			});
		}
	});

	// Convert the map values to an array of tab objects
	const organizedTabs = [...viewMap.values()];
	console.dir(organizedTabs);
	return organizedTabs;
};

_this.getTabInfo = function (viewName) {
	if (!viewName || viewName == "") return;

	const tabElementList = tabSection?.children;

	for (var i = 0; i < tabElementList.length; i++) {
		var tabElement = tabElementList[i];

		var tabInnerText = tabElement.innerText.split("\n")[0].trim();
		if (!tabInnerText || tabElement.role != "tab") return;
		console.log(tabInnerText.replaceAll(" ", ""));

		if (tabInnerText.replaceAll(" ", "") == viewName.replaceAll(" ", "")) {
			return `${viewName.trim()}&${tabElement.id}&${i}`;
		}
	}
};

