	font-size: medium;
}

/* Style for the tab list */
.tab-list {
	list-style-type: none;
	padding: 0;
}

/* Style for each tab item */
.tab-item {
	margin-bottom: 10px;
	border: none;
	padding: 5px;
	display: flex;
	align-items: center;
	list-style: none;
}

/* Style for the tab name */
.tab-name {
	font-size: 16px;
	margin-right: 10px;
}

.tab-container {
	display: flex;
	flex-direction: column;
}

.tab-header {
	display: flex;
	align-items: center;
}

/* Style for the toggle button */
.toggle-btn {
	font-size: 18px;
	cursor: pointer;
	background: none; /* Remove background color */
	border: none; /* Remove border */
	padding: 5px 10px; /* Add padding */
	margin-left: -10px;
	transition: transform 0.1s ease; /*
}

.toggle-btn.collapsed {
	transform: rotate(-90deg);
	/* Rotate the button for the collapsed state */
}

.toggle-btn:active {
	transform: scale(0.95); /* Add a simple click animation */
}

.toggle-btn:hover {
	background-color: #ddd;
	/* Change background color on hover */
}

.tab {
	position: relative;
}

.tab::after {
	content: attr(error-count);
	color: red;
	font-size: 10px;
	position: absolute;
	right: 5px;
	top: 5px;
}

/* Add animation for the highlighted field */
.highlighted-field {
	animation-name: highlight;
	animation-duration: 1.5s;
}

@keyframes highlight {
	from {
		background-color: yellow; /* Change this to the starting highlight color */
	}
	to {
		background-color: initial; /* Change this to the ending background color */
	}
}

.error-list {
	display: none;
	/* Make the error list a block element */
	margin-left: 50px;
	/* Remove default margin */
	padding: 0;
	/* Remove default padding */
}

.message-link {
	cursor: pointer;
}
